"""The contract shared with the TypeScript app (generated by `npm run ai:contract`)."""

from __future__ import annotations

import json
from functools import lru_cache
from pathlib import Path
from typing import Any

CONTRACT_PATH = Path(__file__).with_name("contract.json")


@lru_cache(maxsize=1)
def contract() -> dict[str, Any]:
    return json.loads(CONTRACT_PATH.read_text())


def timed_metrics() -> set[str]:
    return {m["key"] for m in contract()["semantic"]["metrics"] if m["timed"]}


def cost_usd(model: str, usage: dict[str, int]) -> float:
    prices = contract()["pricing"].get(model) or contract()["pricing"][contract()["defaults"]["model"]]
    return (
        usage.get("input", 0) * prices["input"]
        + usage.get("output", 0) * prices["output"]
        + usage.get("cache_read", 0) * prices["cacheRead"]
        + usage.get("cache_write", 0) * prices["cacheWrite"]
    ) / 1_000_000
